336	async fn run_swarm_turn(
337	    backends: Backends,
338	    meta_provider: OpenRouter,
339	    raw_meta_model: String,
340	    mut personas: Vec<Persona>,
341	    default_model: String,
342	    default_provider: OpenRouter,
343	    raw_default_model: String,
344	    base_history: Vec<ChatMessage>,
345	    user_message: String,
346	    session_id: String,
347	    tx: mpsc::UnboundedSender<SwarmMsg>,
348	) {
349	    let send = |u: SwarmUpdate| {
350	        let _ = tx.send((session_id.clone(), u));
351	    };
352	    if personas.is_empty() {
353	        send(SwarmUpdate::Progress("suggesting personas…".to_string()));
354	        match suggest_personas(
355	            &meta_provider,
356	            &raw_meta_model,
357	            &user_message,
358	            &default_model,
359	        )
360	        .await
361	        {
362	            Ok(p) => {
363	                personas = p;
364	                send(SwarmUpdate::RosterSuggested(personas.clone()));
365	            }
366	            Err(e) => {
367	                send(SwarmUpdate::Error(format!(
368	                    "couldn't suggest personas: {e}"
369	                )));
370	                return;
371	            }
372	        }
373	    }
374	    if personas.is_empty() {
375	        send(SwarmUpdate::Error("no personas to run".to_string()));
376	        return;
377	    }
378	
379	    // (persona name, reply content), in speaking order — a running transcript
380	    // every persona converses through. A successful reply marks that persona
381	    // as having answered; the moderator is gated on every current persona
382	    // having answered at least once and on the current round being complete.
383	    let mut discussion: Vec<(String, String)> = Vec::new();
384	    let mut answered: HashSet<String> = HashSet::new();
385	    'convo: for round in 1..=MAX_ROUNDS {
386	        // Snapshot the roster for this round. Personas can only be added by the
387	        // moderator after the round, so everyone in this snapshot gets exactly
388	        // one opportunity before moderation.
389	        let round_personas = personas.clone();
390	        let round_size = round_personas.len();
391	        for (idx, p) in round_personas.into_iter().enumerate() {
392	            send(SwarmUpdate::Progress(format!(
393	                "round {round}/{MAX_ROUNDS} · persona {}/{} — {} is responding",
394	                idx + 1,
395	                round_size,
396	                p.name
397	            )));
398	
399	            let mut messages = base_history.clone();
400	            messages.push(ChatMessage::text(
401	                "system",
402	                format!(
403	                    "You are {} in a live group conversation with the other personas below. \
404	                     Your persona: {}. This discussion proceeds in rounds and every persona \
405	                     gets one response per round. Speak naturally and briefly (a few sentences), \
406	                     stay in character, and actually engage with what the prior speakers said — \
407	                     agree, push back, build on it, or ask a question. Don't just restate your \
408	                     opening position every round.",
409	                    p.name, p.blurb
410	                ),
411	            ));
412	            match render_discussion(&discussion) {
413	                Some(transcript) => messages.push(ChatMessage::text(
414	                    "user",
415	                    format!(
416	                        "Conversation so far:\n\n{transcript}\n\nRound {round}: it's your chance \
417	                         to respond, {}. Engage with what was said.",
418	                        p.name
419	                    ),
420	                )),
421	                None => messages.push(ChatMessage::text(
422	                    "user",
423	                    format!(
424	                        "Round {round}: you're opening the discussion, {}. Give your first take.",
425	                        p.name
426	                    ),
427	                )),
428	            }
429	
430	            let (persona_provider, raw_persona_model) =
431	                backends.resolve(&p.model).unwrap_or_else(|| {
432	                    send(SwarmUpdate::Error(format!(
433	                        "{} model unavailable ({}); using session model",
434	                        p.name, p.model
435	                    )));
436	                    (default_provider.clone(), raw_default_model.clone())
437	                });
438	            match timeout(
439	                Duration::from_secs(120),
440	                persona_provider.complete(&raw_persona_model, messages),
441	            )
442	            .await
443	            .map_err(|_| anyhow::anyhow!("timed out after 120s"))
444	            .and_then(|r| r)
445	            {
446	                Ok(content) => {
447	                    send(SwarmUpdate::Reply {
448	                        persona: p.name.clone(),
449	                        model: p.model.clone(),
450	                        content: content.clone(),
451	                    });
452	                    answered.insert(p.name.clone());
453	                    discussion.push((p.name, content));
454	                }
455	                Err(e) => send(SwarmUpdate::Error(format!("{} failed: {e}", p.name))),
456	            }
457	        }
458	
459	        // The hard cap synthesizes after the final complete round. Never ask
460	        // the moderator to add someone who would have no round left to speak.
461	        if round == MAX_ROUNDS {
462	            break 'convo;
463	        }
464	        if !all_personas_answered(&personas, &answered) {
465	            let missing = personas
466	                .iter()
467	                .filter(|p| !answered.contains(&p.name))
468	                .map(|p| p.name.as_str())
469	                .collect::<Vec<_>>()
470	                .join(", ");
471	            send(SwarmUpdate::Progress(format!(
472	                "round {round} complete — waiting for replies from: {missing}"
473	            )));
474	            continue;
475	        }
476	
477	        send(SwarmUpdate::Progress(format!(
478	            "round {round} complete — moderator checking for a conclusion…"
479	        )));
480	        match moderator_check(&meta_provider, &raw_meta_model, &user_message, &discussion).await {
481	            Ok(ModeratorVerdict::Converged) => break 'convo,
482	            Ok(ModeratorVerdict::Continue) => {}
483	            Ok(ModeratorVerdict::AddPersona { name, blurb }) => {
484	                if personas.len() >= MAX_PERSONAS
485	                    || personas.iter().any(|existing| existing.name == name)
486	                {
487	                    continue;
488	                }
489	                let new_persona = Persona {
490	                    name,
491	                    model: default_model.clone(),
492	                    blurb,
493	                };
494	                send(SwarmUpdate::PersonaJoined(new_persona.clone()));
495	                personas.push(new_persona);
496	            }
497	            Err(_) => break 'convo, // fail safe after a complete, answered round
498	        }
499	    }
500	
501	    send(SwarmUpdate::Progress("writing synthesis…".to_string()));
502	    match synthesize(&meta_provider, &raw_meta_model, &user_message, &discussion).await {
503	        Ok(content) => send(SwarmUpdate::Synthesis(content)),
504	        Err(e) => send(SwarmUpdate::Error(format!("synthesis failed: {e}"))),
505	    }
506	}
