512	fn render_discussion(discussion: &[(String, String)]) -> Option<String> {
513	    if discussion.is_empty() {
514	        return None;
515	    }
516	    Some(
517	        discussion
518	            .iter()
519	            .map(|(name, content)| format!("**{name}**: {content}"))
520	            .collect::<Vec<_>>()
521	            .join("\n\n"),
522	    )
523	}
