482	            Ok(ModeratorVerdict::Continue) => {}
483	            Ok(ModeratorVerdict::AddPersona { name, blurb }) => {
484	                if personas.len() >= MAX_PERSONAS
485	                    || personas.iter().any(|existing| existing.name == name)
486	                {
487	                    continue;
488	                }
489	                let new_persona = Persona {
490	                    name,
491	                    model: default_model.clone(),
492	                    blurb,
493	                };
494	                send(SwarmUpdate::PersonaJoined(new_persona.clone()));
495	                personas.push(new_persona);
496	            }
497	            Err(_) => break 'convo, // fail safe after a complete, answered round
498	        }
499	    }
500	
501	    send(SwarmUpdate::Progress("writing synthesis…".to_string()));
502	    match synthesize(&meta_provider, &raw_meta_model, &user_message, &discussion).await {
503	        Ok(content) => send(SwarmUpdate::Synthesis(content)),
504	        Err(e) => send(SwarmUpdate::Error(format!("synthesis failed: {e}"))),
505	    }
506	}
