 94	
 95	    #[test]
 96	    fn resolve_routes_prefixed_models_to_their_backend_even_with_openrouter_configured() {
 97	        let mut backends = Backends::default();
 98	        backends.set(BackendTag::OpenRouter, OpenRouter::openrouter("or".into()));
 99	        backends.set(BackendTag::OpenAi, OpenRouter::openai("oa".into()));
100	        backends.set(BackendTag::OpencodeGo, OpenRouter::opencode_go("go".into()));
101	        backends.set(BackendTag::Codex, OpenRouter::openai_codex("codex".into()));
102	
103	        let (provider, raw) = backends.resolve("openai:gpt-4.1-mini").unwrap();
104	        assert_eq!(provider.backend_tag(), BackendTag::OpenAi);
105	        assert_eq!(raw, "gpt-4.1-mini");
106	
107	        let (provider, raw) = backends.resolve("opencode:deepseek-v4-flash").unwrap();
108	        assert_eq!(provider.backend_tag(), BackendTag::OpencodeGo);
109	        assert_eq!(raw, "deepseek-v4-flash");
