  1	//! Every backend the app can be logged into at once. Replaces the old
  2	//! single active `self.provider` — since `/model` now merges every
  3	//! configured backend's models into one list, sending a request has to
  4	//! resolve *which* backend a picked model belongs to, not just use "the"
  5	//! provider.
  6	
  7	use crate::provider::openrouter::OpenRouter;
  8	use crate::provider::{BackendTag, Model};
  9	
 10	#[derive(Clone, Default)]
 11	pub struct Backends {
 12	    pub openrouter: Option<OpenRouter>,
 13	    pub openai: Option<OpenRouter>,
 14	    pub opencode: Option<OpenRouter>,
 15	    pub codex: Option<OpenRouter>,
 16	}
 17	
 18	impl Backends {
 19	    pub fn any(&self) -> bool {
 20	        self.openrouter.is_some()
 21	            || self.openai.is_some()
 22	            || self.opencode.is_some()
 23	            || self.codex.is_some()
 24	    }
 25	
 26	    pub fn get(&self, tag: BackendTag) -> Option<&OpenRouter> {
 27	        match tag {
 28	            BackendTag::OpenRouter => self.openrouter.as_ref(),
 29	            BackendTag::OpenAi => self.openai.as_ref(),
 30	            BackendTag::OpencodeGo => self.opencode.as_ref(),
 31	            BackendTag::Codex => self.codex.as_ref(),
 32	        }
 33	    }
 34	
 35	    pub fn set(&mut self, tag: BackendTag, provider: OpenRouter) {
 36	        match tag {
 37	            BackendTag::OpenRouter => self.openrouter = Some(provider),
 38	            BackendTag::OpenAi => self.openai = Some(provider),
 39	            BackendTag::OpencodeGo => self.opencode = Some(provider),
 40	            BackendTag::Codex => self.codex = Some(provider),
 41	        }
 42	    }
 43	
 44	    /// Which backend tags are currently configured, in a fixed display
 45	    /// order — used to drive the model picker's backend filter.
 46	    pub fn configured_tags(&self) -> Vec<BackendTag> {
 47	        [
 48	            BackendTag::OpenRouter,
 49	            BackendTag::OpenAi,
 50	            BackendTag::OpencodeGo,
 51	            BackendTag::Codex,
 52	        ]
 53	        .into_iter()
 54	        .filter(|t| self.get(*t).is_some())
 55	        .collect()
 56	    }
 57	
 58	    /// Split a composite model id (see `composite_id`) into the backend
 59	    /// that owns it and the raw id to actually send in a request, and
 60	    /// clone out that backend's provider. `None` if the composite id's
 61	    /// backend isn't configured (e.g. its login was removed).
 62	    pub fn resolve(&self, composite_id: &str) -> Option<(OpenRouter, String)> {
 63	        for tag in [
 64	            BackendTag::OpenAi,
 65	            BackendTag::OpencodeGo,
 66	            BackendTag::Codex,
 67	        ] {
 68	            if let Some(raw) = composite_id.strip_prefix(tag.key_prefix()) {
 69	                return self.get(tag).cloned().map(|p| (p, raw.to_string()));
 70	            }
 71	        }
 72	        // No known prefix matched => a bare id. Prefer OpenRouter for
 73	        // backwards compatibility with existing stored model choices; if it
 74	        // isn't configured (tests/single-backend setups), use the first
 75	        // configured backend so unprefixed defaults still work.
 76	        self.get(BackendTag::OpenRouter)
 77	            .or_else(|| self.configured_tags().first().and_then(|t| self.get(*t)))
 78	            .cloned()
 79	            .map(|p| (p, composite_id.to_string()))
 80	    }
 81	}
 82	
 83	/// The key used to persist/compare a model choice (favorites, last-used,
 84	/// current-model, per-feature model settings): bare id for OpenRouter
 85	/// (unprefixed, so existing users' saved data keeps working untouched),
 86	/// prefixed for the other three backends since their raw ids can collide.
 87	pub fn composite_id(m: &Model) -> String {
 88	    format!("{}{}", m.backend.key_prefix(), m.id)
 89	}
