403	    pub async fn complete(&self, model: &str, messages: Vec<ChatMessage>) -> Result<String> {
404	        // ChatGPT's Codex endpoint is stream-oriented: non-streaming requests
405	        // are rejected or can return no usable output. Utility jobs (titles,
406	        // memory, compaction, research metadata) still need a one-shot string,
407	        // so collect the same proven SSE path used by interactive chat.
408	        if self.flavor == ProviderFlavor::OpenAiCodex {
409	            let (tx, mut rx) = mpsc::unbounded_channel();
410	            let finish = self
411	                .run_codex_stream(model, &messages, &ChatParams::default(), &[], &tx)
412	                .await?;
413	            drop(tx);
414	
415	            let mut text = String::new();
416	            let mut error = None;
417	            while let Ok(event) = rx.try_recv() {
418	                match event {
419	                    StreamEvent::Token(token) => text.push_str(&token),
420	                    StreamEvent::Error(message) => error = Some(message),
421	                    _ => {}
422	                }
423	            }
