572	enum ModeratorVerdict {
573	    Converged,
574	    Continue,
575	    /// The conversation would benefit from a new voice — its name and a
576	    /// one-sentence personality/perspective blurb.
577	    AddPersona {
578	        name: String,
579	        blurb: String,
580	    },
581	}
582	
583	async fn moderator_check(
584	    provider: &OpenRouter,
585	    meta_model: &str,
586	    topic: &str,
587	    discussion: &[(String, String)],
588	) -> Result<ModeratorVerdict, String> {
589	    let transcript = render_discussion(discussion).unwrap_or_default();
590	    let prompt = format!(
591	        "A panel of personas is having a live conversation about this message:\n\n{topic}\n\n\
592	         Conversation so far:\n\n{transcript}\n\nDecide one of three things and reply with ONLY \
593	         one line, no other text:\n\
594	         - If they've reached a conclusion (agreement, a clear resolution, or a settled \
595	         trade-off), reply exactly: CONVERGED\n\
596	         - If the conversation is missing an important point of view that would meaningfully \
597	         change it, reply exactly: ADD: <short persona name> | <one-sentence personality and \
598	         perspective>\n\
599	         - Otherwise, reply exactly: CONTINUE"
600	    );
601	    let raw = timeout(
602	        Duration::from_secs(30),
603	        provider.complete(meta_model, vec![ChatMessage::text("user", prompt)]),
604	    )
605	    .await
606	    .map_err(|_| "timed out after 30s".to_string())?
607	    .map_err(|e| e.to_string())?;
608	    Ok(parse_moderator_verdict(&raw))
609	}
610	
611	fn parse_moderator_verdict(raw: &str) -> ModeratorVerdict {
612	    // ASCII-only uppercasing so byte offsets stay valid for slicing `raw`
613	    // (full Unicode `to_uppercase` can change a string's byte length).
614	    let upper = raw.to_ascii_uppercase();
615	    if let Some(rest) = upper.find("ADD:").map(|i| &raw[i + 4..]) {
616	        if let Some((name, blurb)) = rest.split_once('|') {
617	            let name = name.trim().trim_matches('*').to_string();
618	            let blurb = blurb.lines().next().unwrap_or("").trim().to_string();
619	            if !name.is_empty() && !blurb.is_empty() {
620	                return ModeratorVerdict::AddPersona { name, blurb };
621	            }
622	        }
623	    }
624	    if upper.contains("CONVERGED") {
625	        return ModeratorVerdict::Converged;
626	    }
627	    ModeratorVerdict::Continue
628	}
629	
630	async fn synthesize(
631	    provider: &OpenRouter,
632	    meta_model: &str,
633	    topic: &str,
634	    discussion: &[(String, String)],
635	) -> Result<String> {
636	    let transcript = render_discussion(discussion).unwrap_or_default();
637	    let prompt = format!(
638	        "A panel of personas had this conversation about a message:\n\n{topic}\n\n\
639	         Conversation:\n\n{transcript}\n\nWrite one final reply to the original message that \
640	         states the conclusion this conversation actually reached — the agreement, resolution, \
641	         or trade-off they settled on — as a clear, useful answer. If they genuinely disagreed \
642	         to the end, say so and give the best-supported call. Markdown allowed. Don't mention \
643	         that this came from a panel — just answer well, informed by the conversation."
644	    );
645	    timeout(
646	        Duration::from_secs(90),
647	        provider.complete(meta_model, vec![ChatMessage::text("user", prompt)]),
648	    )
649	    .await
650	    .map_err(|_| anyhow::anyhow!("timed out after 90s"))?
651	}
